        GlossaryItem("c30", "Scripting", "ಸ್ಕ್ರಿಪ್ಟಿಂಗ್", "ಕೆಲಸಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತಗೊಳಿಸಲು ಬಳಸುವ ಪ್ರೋಗ್ರಾಮಿಂಗ್.", "Computer Science", "/ˈskrɪp.tɪŋ/", "Bash is a popular scripting language."),
        GlossaryItem("c31", "Query", "ಪ್ರಶ್ನೆ", "ದತ್ತಸಂಚಯದಿಂದ ಮಾಹಿತಿಯನ್ನು ಕೇಳುವ ವಿನಂತಿ.", "Computer Science", "/ˈkwɪə.ri/", "SQL is used for database queries."),
        GlossaryItem("c32", "Transaction", "ವ್ಯವಹಾರ", "ದತ್ತಸಂಚಯದಲ್ಲಿ ನಡೆಯುವ ಕೆಲಸದ ಘಟಕ.", "Computer Science", "/trænˈzæk.ʃən/", "Database transactions must be atomic."),
        GlossaryItem("c33", "Indexing", "ಇಂಡೆಕ್ಸಿಂಗ್", "ದತ್ತಾಂಶ ಹುಡುಕಾಟವನ್ನು ವೇಗಗೊಳಿಸುವ ತಂತ್ರ.", "Computer Science", "/ˈɪn.deks.ɪŋ/", "Indexing improves search performance."),
