        GlossaryItem("c38", "Virtual Memory", "ವರ್ಚುವಲ್ ಮೆಮೊರಿ", "ಹಾರ್ಡ್ ಡಿಸ್ಕ್ ಅನ್ನು ರಾಮ್‌ನಂತೆ ಬಳಸುವ ತಂತ್ರ.", "Computer Science", "/ˈvɜː.tʃu.əl ˈmem.ər.i/", "Virtual memory allows large apps to run."),
        GlossaryItem("c39", "Paging", "ಪೇಜಿಂಗ್", "ಮೆಮೊರಿಯನ್ನು ಸಣ್ಣ ಭಾಗಗಳಾಗಿ ನಿರ್ವಹಿಸುವ ವಿಧಾನ.", "Computer Science", "/ˈpeɪ.dʒɪŋ/", "Paging avoids external fragmentation."),
        GlossaryItem("c40", "Segmentation", "ವಿಭಜನೆ", "ಮೆಮೊರಿಯನ್ನು ತಾರ್ಕಿಕ ಭಾಗಗಳಾಗಿ ಹಂಚುವ ವಿಧಾನ.", "Computer Science", "/ˌseɡ.menˈteɪ.ʃən/", "Segmentation is a memory management technique."),
