        GlossaryItem("c42", "Semaphore", "ಸೆಮಾಫೋರ್", "ಸಂಪನ್ಮೂಲಗಳ ಪ್ರವೇಶವನ್ನು ನಿಯಂತ್ರಿಸುವ ವೇರಿಯಬಲ್.", "Computer Science", "/ˈsem.ə.fɔːr/", "Semaphores prevent race conditions."),
        GlossaryItem("c43", "Thread", "ಥ್ರೆಡ್", "ಪ್ರಕ್ರಿಯೆಯೊಳಗಿನ ಒಂದು ಚಿಕ್ಕ ಕೆಲಸದ ಘಟಕ.", "Computer Science", "/θred/", "Multithreading improves app performance."),
        GlossaryItem("c44", "Process", "ಪ್ರಕ್ರಿಯೆ", "ಕಾರ್ಯಗತಗೊಳ್ಳುತ್ತಿರುವ ಪ್ರೋಗ್ರಾಂ.", "Computer Science", "/ˈprəʊ.ses/", "Every app runs as one or more processes."),
        GlossaryItem("c45", "Socket", "ಸಾಕೆಟ್", "ನೆಟ್‌ವರ್ಕ್ ಸಂವಹನದ ಕೊನೆಯ ಬಿಂದು.", "Computer Science", "/ˈsɒk.ɪt/", "Sockets allow communication between apps."),
