        GlossaryItem("g38", "Oceanography", "ಸಾಗರಶಾಸ್ತ್ರ", "ಸಾಗರಗಳು ಮತ್ತು ಅವುಗಳ ಜೀವಿಗಳ ಅಧ್ಯಯನ.", "General", "/ˌəʊ.ʃəˈnɒɡ.rə.fi/", "Oceanography is a vast field."),
        GlossaryItem("g39", "Ecology", "ಪರಿಸರ ವಿಜ್ಞಾನ", "ಜೀವಿಗಳು ಮತ್ತು ಪರಿಸರದ ನಡುವಿನ ಸಂಬಂಧದ ಅಧ್ಯಯನ.", "General", "/iˈkɒl.ə.dʒi/", "Ecology is crucial for conservation."),
        GlossaryItem("g40", "Conservation", "ಸಂರಕ್ಷಣೆ", "ನೈಸರ್ಗಿಕ ಸಂಪನ್ಮೂಲಗಳ ರಕ್ಷಣೆ.", "General", "/ˌkɒn.səˈveɪ.ʃən/", "Water conservation is necessary."),
        GlossaryItem("g41", "Sustainability", "ಸುಸ್ಥಿರತೆ", "ಭವಿಷ್ಯಕ್ಕಾಗಿ ಸಂಪನ್ಮೂಲಗಳನ್ನು ಕಾಯ್ದಿರಿಸುವ ಗುಣ.", "General", "/səˌsteɪ.nəˈbɪl.ə.ti/", "Sustainable energy is the future."),
        GlossaryItem("g42", "Globalization", "ಜಾಗತೀಕರಣ", "ಜಗತ್ತು ಪರಸ್ಪರ ಸಂಪರ್ಕ ಹೊಂದುವ ಪ್ರಕ್ರಿಯೆ.", "General", "/ˌɡləʊ.bəl.aɪˈzeɪ.ʃən/", "Globalization affects local markets."),
        GlossaryItem("g43", "Urbanization", "ನಗರೀಕರಣ", "ನಗರಗಳ ಬೆಳವಣಿಗೆ ಮತ್ತು ವಿಸ್ತರಣೆ.", "General", "/ˌɜː.bən.aɪˈzeɪ.ʃən/", "Urbanization leads to better infrastructure."),
        GlossaryItem("g44", "Migration", "ವಲಸೆ", "ಒಂದು ಪ್ರದೇಶದಿಂದ ಇನ್ನೊಂದಕ್ಕೆ ಹೋಗಿ ವಾಸಿಸುವುದು.", "General", "/maɪˈɡreɪ.ʃən/", "Bird migration is a natural phenomenon."),
        GlossaryItem("g45", "Population", "ಜನಸಂಖ್ಯೆ", "ಒಂದು ಪ್ರದೇಶದಲ್ಲಿ ವಾಸಿಸುವ ಜನರ ಒಟ್ಟು ಸಂಖ್ಯೆ.", "General", "/ˌpɒp.jəˈleɪ.ʃən/", "India has a large population."),
        GlossaryItem("g46", "Census", "ಜನಗಣತಿ", "ಜನಸಂಖ್ಯೆಯ ಅಧಿಕೃತ ಎಣಿಕೆ.", "General", "/ˈsen.səs/", "A census is conducted every ten years."),
        GlossaryItem("g47", "Sovereignty", "ಸಾರ್ವಭೌಮತ್ವ", "ರಾಜ್ಯದ ಸ್ವತಂತ್ರ ಅಧಿಕಾರ.", "General", "/ˈsɒv.rɪn.ti/", "Sovereignty belongs to the people."),
        GlossaryItem("g48", "Constitution", "ಸಂವಿಧಾನ", "ದೇಶದ ಆಡಳಿತಕ್ಕೆ ಬೇಕಾದ ಮೂಲ ನಿಯಮಗಳು.", "General", "/ˌkɒn.stɪˈtʃuː.ʃən/", "The Indian Constitution is the longest written one."),
        GlossaryItem("g49", "Federalism", "ಸಂಯುಕ್ತ ವ್ಯವಸ್ಥೆ", "ಅಧಿಕಾರವನ್ನು ಕೇಂದ್ರ ಮತ್ತು ರಾಜ್ಯಗಳ ನಡುವೆ ಹಂಚುವುದು.", "General", "/ˈfed.ər.əl.ɪ.zəm/", "India follows a federal system."),
        GlossaryItem("g50", "Secularism", "ಜಾತ್ಯತೀತತೆ", "ಎಲ್ಲಾ ಧರ್ಮಗಳನ್ನು ಸಮಾನವಾಗಿ ಕಾಣುವ ತತ್ವ.", "General", "/ˈsek.jə.lə.rɪ.zəm/", "Secularism is a core value of India."),
        GlossaryItem("g51", "Socialism", "ಸಮಾಜವಾದ", "ಸಂಪನ್ಮೂಲಗಳ ಸಮಾನ ಹಂಚಿಕೆಯ ತತ್ವ.", "General", "/ˈsəʊ.ʃəl.ɪ.zəm/", "Socialism aims to reduce inequality."),
        GlossaryItem("g52", "Capitalism", "ಬಂಡವಾಳಶಾಹಿ", "ಖಾಸಗಿ ಮಾಲೀಕತ್ವದ ಆರ್ಥಿಕ ವ್ಯವಸ್ಥೆ.", "General", "/ˈkæp.ɪ.təl.ɪ.zəm/", "Capitalism encourages competition."),
        GlossaryItem("g53", "Communism", "ಕಮ್ಯುನಿಸಂ", "ಎಲ್ಲಾ ಆಸ್ತಿ ಸಾರ್ವಜನಿಕವಾಗಿರುವ ವ್ಯವಸ್ಥೆ.", "General", "/ˈkɒm.jə.nɪ.zəm/", "Communism seeks a classless society."),
        GlossaryItem("g54", "Human Rights", "ಮಾನವ ಹಕ್ಕುಗಳು", "ಎಲ್ಲಾ ಮಾನವರಿಗೆ ಹುಟ್ಟಿನಿಂದ ಬರುವ ಮೂಲಭೂತ ಹಕ್ಕುಗಳು.", "General", "/ˈhjuː.mən ˌraɪts/", "Human rights protect individual dignity.")
    )
}

